Lemma lr_bytes_W : forall (n : nat) C Ar A mB md (s data wpl h buf tab kd line : Z) (S : TSet) (r0 r : bvmap 5 word) (m : word -> option byte) (j db : Z),
  Cok C -> W C A m md -> sub_live Ar A ->
  live A (Z_to_bv 64 data) = Some kd -> (4 * wpl * h <= kd)%Z -> live Ar (Z_to_bv 64 data) = None -> live (c_A0 C) (Z_to_bv 64 data) = None ->
  live A (Z_to_bv 64 buf) = Some (wpl * 4)%Z -> live A (Z_to_bv 64 tab) = Some 256%Z ->
  (0 <= data < 2 ^ 64)%Z -> (0 <= buf < 2 ^ 64)%Z -> (0 <= tab < 2 ^ 64)%Z -> (buf mod 4 = 0)%Z ->
  (1 <= wpl)%Z -> (1 <= h)%Z -> (4 * wpl * h <= 2 ^ 26)%Z ->
  (data <= line)%Z -> (line + 4 * wpl <= data + 4 * wpl * h)%Z -> (line mod 4 = 0)%Z ->
  (1 <= db <= 4 * wpl)%Z -> (0 <= j)%Z -> (Z.of_nat n = db - 1 - j)%Z ->
  POSTM C Ar s mB m ->
  (forall a : word, ~ (data <= u a < data + 4 * wpl * h)%Z -> ~ (buf <= u a < buf + 4 * wpl)%Z -> ~ scratch C (s - 128) a -> m a = mB a) ->
  regs_agree (fun x => In x [10; 11; 12; 13]%list) r0 r ->
  getr r 19 = Z_to_bv 64 buf -> getr r 9 = Z_to_bv 64 tab -> getr r 10 = Z_to_bv 64 (line + j) -> getr r 11 = Z_to_bv 64 (4 * wpl - 1 - j) ->
  getr r 25 = Z_to_bv 64 (4 * wpl - 1 - db) ->
  (forall m' r', W C A m' md -> POSTM C Ar s mB m' ->
     (forall a : word, ~ (data <= u a < data + 4 * wpl * h)%Z -> ~ (buf <= u a < buf + 4 * wpl)%Z -> ~ scratch C (s - 128) a -> m' a = mB a) ->
     regs_agree (fun x => In x [10; 11; 12; 13]%list) r0 r' ->
     realizes SEGS (mkCfg (mkst r' (0x887ac : word) m' al_rom) md) S) ->
  realizes SEGS (mkCfg (mkst r (0x887e0 : word) m al_rom) md) S.
