(* [comment removed for export] *)
Lemma lr_rows_W : forall (n : nat) C Ar A mB md (s data wpl h w buf tab kd : Z) (S : TSet) (r0 r : bvmap 5 word) (m : word -> option byte) (i : Z),
  Cok C -> W C A m md -> sub_live Ar A ->
  live A (Z_to_bv 64 data) = Some kd -> (4 * wpl * h <= kd)%Z -> live Ar (Z_to_bv 64 data) = None -> live (c_A0 C) (Z_to_bv 64 data) = None ->
  live A (Z_to_bv 64 buf) = Some (wpl * 4)%Z -> live Ar (Z_to_bv 64 buf) = None -> live (c_A0 C) (Z_to_bv 64 buf) = None ->
  live A (Z_to_bv 64 tab) = Some 256%Z -> Z_to_bv 64 buf <> Z_to_bv 64 data ->
  (0 <= data < 2 ^ 64)%Z -> (0 <= buf < 2 ^ 64)%Z -> (0 <= tab < 2 ^ 64)%Z -> (data mod 4 = 0)%Z -> (buf mod 4 = 0)%Z ->
  (1 <= wpl < 2 ^ 29)%Z -> (1 <= h < 2 ^ 31)%Z -> (4 * wpl * h <= 2 ^ 26)%Z -> (1 <= w < 2 ^ 30)%Z -> (w <= 32 * wpl)%Z ->
  (0 <= i)%Z -> (Z.of_nat n = h - 1 - i)%Z -> (c_top C - LSTK <= s - 128)%Z -> (s <= c_top C)%Z ->
  rdn SEGS m (Z_to_bv 64 (s - 112)) 4 = Some (word_to_le_bytes 4 (Z_to_bv 64 h)) ->
  POSTM C Ar s mB m ->
  (forall a : word, ~ (data <= u a < data + 4 * wpl * h)%Z -> ~ (buf <= u a < buf + 4 * wpl)%Z -> ~ scratch C (s - 128) a -> m a = mB a) ->
  (forall x, In x [2; 3; 4; 8; 9; 18; 19; 20; 21; 23; 24; 25; 27]%list -> getr r x = getr r0 x) ->
  getr r 2 = Z_to_bv 64 (s - 128) -> getr r 8 = Z_to_bv 64 data -> getr r 9 = Z_to_bv 64 tab -> getr r 18 = Z_to_bv 64 wpl ->
  getr r 19 = Z_to_bv 64 buf -> getr r 20 = Z_to_bv 64 (4 * wpl) -> getr r 21 = Z_to_bv 64 w -> getr r 23 = Z_to_bv 64 (4 * wpl - 1) ->
  getr r 24 = Z_to_bv 64 (4 * wpl) -> getr r 25 = Z_to_bv 64 (4 * wpl - 1 - (w + 7) / 8) ->
  getr r 22 = Z_to_bv 64 i -> getr r 26 = Z_to_bv 64 (data + 4 * wpl * i) ->
  (forall m' r', W C A m' md -> POSTM C Ar s mB m' ->
     (forall a : word, ~ (data <= u a < data + 4 * wpl * h)%Z -> ~ (buf <= u a < buf + 4 * wpl)%Z -> ~ scratch C (s - 128) a -> m' a = mB a) ->
     (forall x, In x [2; 3; 4; 8; 9; 18; 19; 20; 21; 23; 24; 25; 27]%list -> getr r' x = getr r0 x) ->
     getr r' 1 = Z_to_bv 64 0x88bb4 -> getr r' 10 = Z_to_bv 64 buf ->
     realizes SEGS (mkCfg (mkst r' (0xfa374 : word) m' al_rom) md) S) ->
